import 'dart:convert';

import 'package:flutter/services.dart';

/// How well the table knows a code.
enum DtcKnowledge {
  /// In the table: its own description.
  described,

  /// A generic range, but not in the table: only the system it belongs to.
  systemOnly,

  /// A manufacturer's range (P1, B1, U1…): no public table.
  manufacturer,

  /// Neither: a range the table does not cover at all.
  unknown,
}

/// The generic trouble codes in Portuguese (`assets/obd/dtc_generic_pt.json`,
/// generated by `tool/obd/gerar_tabela_dtc.py`; §7.1 of the design).
class DtcCatalog {
  DtcCatalog({required this.codes, required this.systems, required this.manufacturerRanges});

  factory DtcCatalog.fromJson(Map<String, Object?> json) => DtcCatalog(
        codes: (json['codigos'] as Map).cast<String, String>(),
        systems: (json['sistemas'] as Map).cast<String, String>(),
        manufacturerRanges: (json['faixasDoFabricante'] as List).cast<String>(),
      );

  static const assetPath = 'assets/obd/dtc_generic_pt.json';

  static DtcCatalog? _loaded;

  /// The table, read once from the app's assets.
  static Future<DtcCatalog> load([AssetBundle? bundle]) async {
    final loaded = _loaded;
    if (loaded != null) return loaded;
    final text = await (bundle ?? rootBundle).loadString(assetPath);
    return _loaded = DtcCatalog.fromJson((jsonDecode(text) as Map).cast<String, Object?>());
  }

  final Map<String, String> codes;

  /// The system of each generic range, by its first three characters.
  final Map<String, String> systems;
  final List<String> manufacturerRanges;

  int get length => codes.length;

  DtcKnowledge knowledge(String code) {
    final c = code.toUpperCase();
    if (codes.containsKey(c)) return DtcKnowledge.described;
    if (manufacturerRanges.any(c.startsWith)) return DtcKnowledge.manufacturer;
    if (c.length >= 3 && systems.containsKey(c.substring(0, 3))) return DtcKnowledge.systemOnly;
    return DtcKnowledge.unknown;
  }

  /// The code in words, as the report shows it.
  String describe(String code) {
    final c = code.toUpperCase();
    return switch (knowledge(c)) {
      DtcKnowledge.described => codes[c]!,
      DtcKnowledge.manufacturer => 'Código do fabricante: consulte a concessionária ou um scanner da marca',
      DtcKnowledge.systemOnly => 'Código genérico de ${systems[c.substring(0, 3)]} (sem descrição na tabela)',
      DtcKnowledge.unknown => 'Código sem descrição na tabela',
    };
  }
}
